private function executeComposerInstall($host)
    {
        $ssh = $host->getSshClient();
        $ssh->exec(array(
            sprintf('cd %s;', $host->getWorkingDirectory()),
            'stat composer.phar'
        ));
        if ($ssh->getExitCode()) {
            $this->installComposer($host);
        }
        $ssh = $host->getSshClient();
        $ssh->exec(
            array(
                sprintf('cd %s;', $host->getWorkingDirectory()),
                'php composer.phar install --no-dev'
            ),
            null,
            self::TIMEOUT_MAX_RUNTIME_COMPOSER_INSTALL
        );
        if ($ssh->getExitCode()) {
            throw new SynchronisationException($host->getName(), sprintf(
                'Unable to execute composer install: "%s".',
                $ssh->getErrorOutput()
            ));
        }
    }

public static double Mean( int[] values ) {
        int     hits;
        long    total = 0;
        double  mean = 0;

        // for all values
        for ( int i = 0, n = values.length; i < n; i++ ) {
            hits = values[i];
            // accumulate mean
            mean += i * hits;
            // accumalate total
            total += hits;
        }
        return ( total == 0 ) ? 0 : mean / total;
    }

