private void update(){

        total = 0;
        for (int i = 0; i < values.length; i++) {
            total += values[i];
        }

        mean   = HistogramStatistics.Mean( values );
        stdDev = HistogramStatistics.StdDev( values, mean );
        kurtosis = HistogramStatistics.Kurtosis(values, mean, stdDev);
