            return array();
        }

        $dirh = @opendir($path); //directory handler
//$recursion  = 0;
        $found = [];

        if ($dirh) {
            while (false !== ($file = readdir($dirh))) {
                // remove '.' and '..'
                if ($file == '.' || $file == '..' || in_array($file, $exclude)) {
                    continue;
                }

                $recursion = 0;
                $newPath = $path . $file;

                if ($this->isFolder($newPath) && $recursive && ($recursion < $recursiveLimit)) {
                    //echo $this->is($newPath)."<br />";
