                    $found = array_merge($items, $found);
                }

                $found[] = $newPath;
            }
            closedir($dirh);
        }

//@TODO if long, get additional info for each path;

        return $found;
    }

protected function getNetwork(): array
	{
		$network = [];
		$data = $this->readFile('/proc/net/dev');

		if ($data !== null) {
			$bufe = preg_split("/\n/", $data, -1, PREG_SPLIT_NO_EMPTY);
			unset($bufe[0], $bufe[1]);
			foreach ($bufe as $buf) {
				list($dev_name, $stats_list) = preg_split('/:/', $buf, 2);
				$stats = preg_split('/\s+/', trim($stats_list));

				$dev = new Obj;
				$dev->name = trim($dev_name);
				$dev->recieve = (int) $stats[0];
				$dev->sent = (int) $stats[8];
				$dev->error = (int) $stats[2] + (int) $stats[10];
				$dev->drop = (int) $stats[3] + (int) $stats[11];

				$ipBuff = preg_split("/\n/", $this->readCommand('ip addr show ' . $dev->name), -1, PREG_SPLIT_NO_EMPTY);
				foreach ($ipBuff as $line) {
					if (preg_match('/^\s*link\/ether\s+(.*)\s+brd.*/i', $line, $ar_buf)) {
						$dev->mac = $ar_buf[1];
					} elseif (preg_match('/^\s*inet6\s+(.*)\/.*/i', $line, $ar_buf)) {
						$dev->ip6 = $ar_buf[1];
					} elseif (preg_match('/^\s*inet\s+(.*)\/.*/i', $line, $ar_buf)) {
						$dev->ip = $ar_buf[1];
					}
				}
				$network[] = $dev;
			}
		}
		return $network;
	}

function (srcDirectory) {
  let manifest
  let manifestContent

  try {
    manifestContent = fs.readFileSync(path.join(srcDirectory, 'manifest.json'))
  } catch (readError) {
    console.warn(`Reading ${path.join(srcDirectory, 'manifest.json')} failed.`)
    console.warn(readError.stack || readError)
    throw readError
  }

  try {
    manifest = JSON.parse(manifestContent)
  } catch (parseError) {
    console.warn(`Parsing ${path.join(srcDirectory, 'manifest.json')} failed.`)
    console.warn(parseError.stack || parseError)
    throw parseError
  }

  if (!manifestNameMap[manifest.name]) {
    const extensionId = generateExtensionIdFromName(manifest.name)
    manifestMap[extensionId] = manifestNameMap[manifest.name] = manifest
    Object.assign(manifest, {
      srcDirectory: srcDirectory,
      extensionId: extensionId,
      // We can not use 'file://' directly because all resources in the extension
      // will be treated as relative to the root in Chrome.
      startPage: url.format({
        protocol: 'chrome-extension',
        slashes: true,
        hostname: extensionId,
        pathname: manifest.devtools_page
      })
    })
    return manifest
  } else if (manifest && manifest.name) {
    console.warn(`Attempted to load extension "${manifest.name}" that has already been loaded.`)
    return manifest
  }
}

